const PptxGenJS = require('pptxgenjs');
const pres = new PptxGenJS();

pres.layout = 'LAYOUT_WIDE'; // 13.33 x 7.5 inches
pres.author = 'WorkspaceX';
pres.title = '团队协作：打造高效能团队';

// Color palette
const C = {
  primary: '1B3A5C',    // deep navy
  accent: '2E86AB',     // teal blue
  highlight: 'F4A261',  // warm orange
  light: 'EDF2F7',      // light gray bg
  dark: '1A202C',       // near-black text
  white: 'FFFFFF',
  sub: '4A5568',        // subtitle gray
};

const FONT = '微软雅黑';

// ─── Helper functions ───
function addFooter(slide, pageNum) {
  slide.addText(`${pageNum} / 5`, {
    x: 12.0, y: 7.0, w: 1.0, h: 0.35,
    fontSize: 10, color: C.sub, fontFace: FONT, align: 'right'
  });
  // Accent line at bottom
  slide.addShape(pres.ShapeType.rect, {
    x: 0, y: 7.25, w: 13.33, h: 0.25, fill: { color: C.accent }
  });
}

function addSectionTitle(slide, title, subtitle) {
  slide.addText(title, {
    x: 0.8, y: 0.4, w: 11.5, h: 0.8,
    fontSize: 30, bold: true, color: C.primary, fontFace: FONT
  });
  if (subtitle) {
    slide.addText(subtitle, {
      x: 0.8, y: 1.15, w: 11.5, h: 0.45,
      fontSize: 14, color: C.sub, fontFace: FONT
    });
  }
  // Divider line
  slide.addShape(pres.ShapeType.rect, {
    x: 0.8, y: 1.65, w: 2.5, h: 0.06, fill: { color: C.highlight }
  });
}

// ════════════════════════════════════════
// Slide 1 — Title Page
// ════════════════════════════════════════
const s1 = pres.addSlide();
s1.background = { fill: C.primary };

// Decorative circle
s1.addShape(pres.ShapeType.ellipse, {
  x: 9.5, y: -1.5, w: 5.5, h: 5.5,
  fill: { color: C.accent, transparency: 70 }
});
s1.addShape(pres.ShapeType.ellipse, {
  x: -1.5, y: 4.5, w: 4.5, h: 4.5,
  fill: { color: C.highlight, transparency: 75 }
});

s1.addText('团队协作', {
  x: 1.2, y: 2.0, w: 10, h: 1.4,
  fontSize: 52, bold: true, color: C.white, fontFace: FONT
});
s1.addText('打造高效能团队的五大核心要素', {
  x: 1.2, y: 3.4, w: 10, h: 0.7,
  fontSize: 22, color: C.light, fontFace: FONT
});
s1.addShape(pres.ShapeType.rect, {
  x: 1.2, y: 4.3, w: 3.0, h: 0.07, fill: { color: C.highlight }
});
s1.addText('2024 · 内部培训', {
  x: 1.2, y: 4.7, w: 5, h: 0.5,
  fontSize: 14, color: C.light, fontFace: FONT
});

// ════════════════════════════════════════
// Slide 2 — Why Team Collaboration Matters
// ════════════════════════════════════════
const s2 = pres.addSlide();
s2.background = { fill: C.white };
addSectionTitle(s2, '为什么需要团队协作？', '协作不是口号，而是组织竞争力的底层能力');
addFooter(s2, 2);

const reasons = [
  { icon: '🎯', title: '目标对齐', desc: '统一方向，减少重复劳动\n让每个人的努力都指向同一个结果' },
  { icon: '⚡', title: '效率倍增', desc: '分工互补，缩短交付周期\n1+1 > 2 的协同效应' },
  { icon: '💡', title: '创新涌现', desc: '多元视角碰撞激发创意\n跨职能合作催生突破性方案' },
  { icon: '🛡️', title: '风险共担', desc: '信息透明降低决策盲区\n互相补位增强组织韧性' },
];

reasons.forEach((r, i) => {
  const col = i % 2;
  const row = Math.floor(i / 2);
  const bx = 0.8 + col * 6.0;
  const by = 2.1 + row * 2.5;

  // Card background
  s2.addShape(pres.ShapeType.roundRect, {
    x: bx, y: by, w: 5.5, h: 2.1, rectRadius: 0.15,
    fill: { color: C.light }, shadow: { type: 'outer', blur: 6, offset: 2, color: 'CCCCCC', opacity: 0.3 }
  });
  // Icon
  s2.addText(r.icon, {
    x: bx + 0.3, y: by + 0.3, w: 0.8, h: 0.8,
    fontSize: 32, align: 'center', valign: 'middle'
  });
  // Title
  s2.addText(r.title, {
    x: bx + 1.2, y: by + 0.25, w: 3.8, h: 0.5,
    fontSize: 18, bold: true, color: C.primary, fontFace: FONT
  });
  // Description
  s2.addText(r.desc, {
    x: bx + 1.2, y: by + 0.8, w: 3.8, h: 1.1,
    fontSize: 12, color: C.sub, fontFace: FONT, lineSpacingMultiple: 1.3
  });
});

// ════════════════════════════════════════
// Slide 3 — Five Core Elements
// ════════════════════════════════════════
const s3 = pres.addSlide();
s3.background = { fill: C.white };
addSectionTitle(s3, '高效协作的五大核心要素', '从信任到执行，构建完整的协作闭环');
addFooter(s3, 3);

